COMPILED=[(k,label,[(w,re.compile(p)) for w,p in pats]) for k,label,pats in TOPICS]

def score_all(text):
    out=[]
    for k,label,pats in COMPILED:
        s=sum(w*len(rx.findall(text)) for w,rx in pats)
        if s: out.append((s,k,label))
    out.sort(key=lambda x:-x[0])
    return out

def classify(text):
    s=score_all(text)
    if not s: return None
    return s[0][1], s[0][2], s[0][0], (s[0][0]-s[1][0] if len(s)>1 else s[0][0])
